# This project we have a info about car company and we will create a RAG which can answer based on the avaialbale text docs present for that company 

# Step -1 : Document Loading ( Muliple docs via DirectoryLoader ) 

from google import genai
from langchain_community.document_loaders import TextLoader , DirectoryLoader

loader = DirectoryLoader ( 
"data/" , 
glob = "**/*.txt", 
loader_cls = TextLoader
)  

docs = loader.load()

# Here we are reading all the files present in the data folder using TextLoader 
# For reading multiple files we use DirectoryLoader and specify the glob pattern to read all the files with .txt extension


# Step - 2 : Text Splitting ( Split docs into Chunks )

from langchain_text_splitters import RecursiveCharacterTextSplitter

text_splitter = RecursiveCharacterTextSplitter(
    chunk_size = 1000 ,
    chunk_overlap = 200 
)
chunks = text_splitter.split_documents(docs)

print(chunks[0].page_content)  # This will print the first chunk of the document after splitting


# Step -3 Create Embeddings ( Convert text into vector representation )

from langchain_google_genai import GoogleGenerativeAIEmbeddings
import os 
from dotenv import load_dotenv
load_dotenv()


embeddings = GoogleGenerativeAIEmbeddings(
    model = "gemini-embedding-2",
    google_api_key = os.getenv("GOOGLE_API_KEY")
)

print(embeddings.embed_query(chunks[0].page_content))  # It will give embedding for Hii

